package ca.yorku.eecs3311.coursepilot.application.agent; import org.springframework.stereotype.Component; import java.util.*; @Component public class ResponseSynthesizer {public String synthesize(AgentIntent intent,List<AgentTool.ToolResult> results,List<?> memory){StringBuilder b=new StringBuilder("CoursePilot agent · ").append(intent.name()).append("\n");for(var r:results)b.append(r.success()?"✓ ":"⚠ ").append(r.tool()).append(": ").append(r.output()).append("\n");if(!memory.isEmpty())b.append("Recent learning activity considered: ").append(memory.size()).append(" event(s).\n");return b.toString().trim();}}
